import { useMemo, useState } from 'react'

type Transaction = {
  id: string
  customer: string
  initials: string
  date: string
  category: string
  amount: number
  status: 'Completed' | 'Pending'
}

type SortKey = 'customer' | 'date' | 'category' | 'amount' | 'status'
type DateRange = 'This month' | 'This quarter' | 'This year'
type Page = 'overview' | 'customers'

const monthlyRevenue = [
  { month: 'Jan', amount: 38200 },
  { month: 'Feb', amount: 44750 },
  { month: 'Mar', amount: 42100 },
  { month: 'Apr', amount: 51800 },
  { month: 'May', amount: 49350 },
  { month: 'Jun', amount: 61750 },
  { month: 'Jul', amount: 58400 },
  { month: 'Aug', amount: 67200 },
  { month: 'Sep', amount: 63400 },
  { month: 'Oct', amount: 72100 },
  { month: 'Nov', amount: 68950 },
  { month: 'Dec', amount: 79400 },
]

const transactions: Transaction[] = [
  { id: 'INV-1048', customer: 'Olivia Martin', initials: 'OM', date: 'Dec 18, 2024', category: 'Subscriptions', amount: 1240.00, status: 'Completed' },
  { id: 'INV-1047', customer: 'Liam Johnson', initials: 'LJ', date: 'Dec 17, 2024', category: 'Consulting', amount: 2850.00, status: 'Completed' },
  { id: 'INV-1046', customer: 'Sophia Williams', initials: 'SW', date: 'Dec 16, 2024', category: 'Software', amount: 640.00, status: 'Pending' },
  { id: 'INV-1045', customer: 'Noah Brown', initials: 'NB', date: 'Dec 15, 2024', category: 'Subscriptions', amount: 890.00, status: 'Completed' },
  { id: 'INV-1044', customer: 'Emma Davis', initials: 'ED', date: 'Dec 14, 2024', category: 'Consulting', amount: 1750.00, status: 'Completed' },
  { id: 'INV-1043', customer: 'James Wilson', initials: 'JW', date: 'Dec 12, 2024', category: 'Software', amount: 420.00, status: 'Completed' },
  { id: 'INV-1042', customer: 'Ava Taylor', initials: 'AT', date: 'Nov 28, 2024', category: 'Subscriptions', amount: 980.00, status: 'Completed' },
  { id: 'INV-1041', customer: 'William Anderson', initials: 'WA', date: 'Nov 21, 2024', category: 'Consulting', amount: 2100.00, status: 'Completed' },
  { id: 'INV-1040', customer: 'Mia Thomas', initials: 'MT', date: 'Oct 30, 2024', category: 'Software', amount: 760.00, status: 'Pending' },
  { id: 'INV-1039', customer: 'Henry Jackson', initials: 'HJ', date: 'Sep 18, 2024', category: 'Consulting', amount: 3200.00, status: 'Completed' },
]

const formatCurrency = (value: number) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(value)
const formatAmount = (value: number) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2 }).format(value)

function Icon({ name, size = 18 }: { name: string; size?: number }) {
  const common = { width: size, height: size, viewBox: '0 0 24 24', fill: 'none', stroke: 'currentColor', strokeWidth: 1.8, strokeLinecap: 'round' as const, strokeLinejoin: 'round' as const }
  const paths: Record<string, React.ReactNode> = {
    grid: <><rect x="3" y="3" width="7" height="7" rx="1" /><rect x="14" y="3" width="7" height="7" rx="1" /><rect x="3" y="14" width="7" height="7" rx="1" /><rect x="14" y="14" width="7" height="7" rx="1" /></>,
    chart: <><path d="M4 19V5" /><path d="M4 19h17" /><path d="m7 15 3-4 3 2 5-7" /></>,
    card: <><rect x="3" y="5" width="18" height="14" rx="2" /><path d="M3 10h18" /><path d="M7 15h3" /></>,
    users: <><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2" /><circle cx="9" cy="7" r="4" /><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75" /></>,
    settings: <><circle cx="12" cy="12" r="3" /><path d="M19.4 15a1.7 1.7 0 0 0 .34 1.88l.06.06-1.7 1.7-.06-.06a1.7 1.7 0 0 0-1.88-.34 1.7 1.7 0 0 0-1.03 1.56V20h-2.4v-.2a1.7 1.7 0 0 0-1.03-1.56 1.7 1.7 0 0 0-1.88.34l-.06.06-1.7-1.7.06-.06A1.7 1.7 0 0 0 8.4 15a1.7 1.7 0 0 0-1.56-1.03H6v-2.4h.2A1.7 1.7 0 0 0 7.76 10a1.7 1.7 0 0 0-.34-1.88l-.06-.06 1.7-1.7.06.06A1.7 1.7 0 0 0 11 6.1a1.7 1.7 0 0 0 1.03-1.56V4h2.4v.2A1.7 1.7 0 0 0 15.46 5.8a1.7 1.7 0 0 0 1.88-.34l.06-.06 1.7 1.7-.06.06A1.7 1.7 0 0 0 18.7 9a1.7 1.7 0 0 0 1.56 1.03h.2v2.4h-.2A1.7 1.7 0 0 0 19.4 15Z" /></>,
    bell: <><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4" /></>,
    download: <><path d="M12 3v12" /><path d="m7 10 5 5 5-5M5 21h14" /></>,
    arrow: <><path d="m5 12 4 4L19 6" /></>,
    chevron: <path d="m6 9 6 6 6-6" />,
  }
  return <svg {...common}>{paths[name]}</svg>
}

export default function App() {
  const [page, setPage] = useState<Page>('overview')
  const [customerSearch, setCustomerSearch] = useState('')
  const [sortKey, setSortKey] = useState<SortKey>('date')
  const [ascending, setAscending] = useState(false)
  const [range, setRange] = useState<DateRange>('This year')

  const filteredTransactions = useMemo(() => transactions.filter(transaction => {
    const month = new Date(transaction.date).getMonth()
    if (range === 'This month') return month === 11
    if (range === 'This quarter') return month >= 9 && month <= 11
    return true
  }), [range])

  const rangeTotal = filteredTransactions.reduce((sum, item) => sum + item.amount, 0)
  const sortedTransactions = useMemo(() => [...filteredTransactions].sort((a, b) => {
    const first = a[sortKey].toString()
    const second = b[sortKey].toString()
    const result = sortKey === 'amount' ? a.amount - b.amount : first.localeCompare(second)
    return ascending ? result : -result
  }), [filteredTransactions, sortKey, ascending])

  const sortBy = (key: SortKey) => {
    if (key === sortKey) setAscending(!ascending)
    else { setSortKey(key); setAscending(true) }
  }

  const max = Math.max(...monthlyRevenue.map(item => item.amount))
  const customerRows = useMemo(() => {
    const grouped = new Map<string, { customer: string; initials: string; spend: number; orders: number; lastOrder: string; lastTime: number }>()
    transactions.forEach(transaction => {
      const existing = grouped.get(transaction.customer)
      const time = new Date(transaction.date).getTime()
      if (existing) {
        existing.spend += transaction.amount
        existing.orders += 1
        if (time > existing.lastTime) { existing.lastOrder = transaction.date; existing.lastTime = time }
      } else grouped.set(transaction.customer, { customer: transaction.customer, initials: transaction.initials, spend: transaction.amount, orders: 1, lastOrder: transaction.date, lastTime: time })
    })
    return [...grouped.values()].filter(item => item.customer.toLowerCase().includes(customerSearch.toLowerCase()))
  }, [customerSearch])

  return (
    <div className="min-h-screen bg-[#f7f8fa] text-[#17202d]">
      <aside className="fixed hidden h-screen w-[244px] border-r border-[#e7eaf0] bg-white px-5 py-7 lg:block">
