        <nav className="mt-12 space-y-1 text-[13px] font-medium text-[#718096]">
          <a onClick={() => setPage('overview')} className={`flex items-center gap-3 rounded-lg px-3 py-2.5 ${page === 'overview' ? 'bg-[#eaf5f1] text-[#176b55]' : 'hover:bg-gray-50'}`} href="#"><Icon name="grid" /> Overview</a>
          <a className="flex items-center gap-3 rounded-lg px-3 py-2.5 hover:bg-gray-50" href="#"><Icon name="chart" /> Revenue</a>
          <a className="flex items-center gap-3 rounded-lg px-3 py-2.5 hover:bg-gray-50" href="#"><Icon name="card" /> Transactions</a>
          <a onClick={() => setPage('customers')} className={`flex items-center gap-3 rounded-lg px-3 py-2.5 ${page === 'customers' ? 'bg-[#eaf5f1] text-[#176b55]' : 'hover:bg-gray-50'}`} href="#"><Icon name="users" /> Customers</a>
        </nav>
        <div className="mt-[360px] border-t border-[#eef0f3] pt-5 text-[13px] font-medium text-[#718096]"><a className="flex items-center gap-3 px-3 py-2.5" href="#"><Icon name="settings" /> Settings</a></div>
        <div className="absolute bottom-7 left-7 right-7 flex items-center gap-2.5"><div className="grid h-8 w-8 place-items-center rounded-full bg-[#d9e7e2] text-xs font-semibold text-[#176b55]">JD</div><div><p className="text-xs font-semibold">Jordan Davis</p><p className="text-[11px] text-[#8993a2]">Admin</p></div><span className="ml-auto text-[#9aa4b2]">•••</span></div>
      </aside>

      <div className="lg:ml-[244px]">
        <header className="flex h-[76px] items-center justify-between border-b border-[#e7eaf0] bg-white px-6 sm:px-10">
          <div><p className="text-[11px] font-semibold uppercase tracking-[0.14em] text-[#9aa4b2]">Workspace / Analytics</p><h1 className="mt-1 text-xl font-bold tracking-[-0.03em]">{page === 'overview' ? 'Revenue overview' : 'Customers'}</h1></div>
          <div className="flex items-center gap-4"><button className="relative text-[#718096]"><Icon name="bell" /><span className="absolute -right-0.5 -top-0.5 h-1.5 w-1.5 rounded-full bg-[#e2684e]" /></button><div className="hidden h-7 w-px bg-[#e7eaf0] sm:block" /><button className="hidden items-center gap-2 rounded-lg border border-[#e2e6eb] px-3 py-2 text-xs font-semibold text-[#536173] sm:flex"><Icon name="download" size={15} /> Export report</button></div>
        </header>

        <main className="mx-auto max-w-[1400px] px-6 py-8 sm:px-10">
          {page === 'customers' ? <section>
            <div className="mb-7"><h2 className="text-2xl font-bold tracking-[-0.04em]">Customers</h2><p className="mt-1 text-sm text-[#8791a0]">Understand your customers and their purchasing activity.</p></div>
            <div className="mb-5 flex items-center gap-3 rounded-xl border border-[#e5e9ee] bg-white px-4 py-3 shadow-[0_2px_7px_rgba(20,35,50,0.02)]"><span className="text-[#9aa4b2]">⌕</span><input value={customerSearch} onChange={event => setCustomerSearch(event.target.value)} placeholder="Search customers" className="w-full bg-transparent text-sm outline-none placeholder:text-[#aab2bd]" /></div>
            <div className="overflow-hidden rounded-xl border border-[#e5e9ee] bg-white shadow-[0_2px_7px_rgba(20,35,50,0.02)]"><div className="border-b border-[#edf0f3] px-6 py-5"><h3 className="text-[15px] font-bold">All customers</h3><p className="mt-1 text-xs text-[#8b96a5]">{customerRows.length} customers found</p></div><div className="overflow-x-auto"><table className="w-full min-w-[650px] text-left"><thead className="bg-[#fbfcfd] text-[10px] font-semibold uppercase tracking-[0.1em] text-[#9aa4b2]"><tr><th className="px-6 py-3.5">Customer</th><th className="px-6 py-3.5">Total spend</th><th className="px-6 py-3.5">Orders</th><th className="px-6 py-3.5">Last order date</th></tr></thead><tbody className="divide-y divide-[#f0f2f5]">{customerRows.map(item => <tr key={item.customer} className="text-[13px] hover:bg-[#fbfdfc]"><td className="px-6 py-4"><div className="flex items-center gap-3"><div className="grid h-8 w-8 place-items-center rounded-full bg-[#e7f1ed] text-[10px] font-bold text-[#176b55]">{item.initials}</div><span className="font-semibold text-[#273342]">{item.customer}</span></div></td><td className="px-6 py-4 font-semibold text-[#273342]">{formatAmount(item.spend)}</td><td className="px-6 py-4 text-[#687588]">{item.orders}</td><td className="px-6 py-4 text-[#687588]">{item.lastOrder}</td></tr>)}</tbody></table></div></div>
          </section> : <>
          <div className="mb-4 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><h2 className="text-2xl font-bold tracking-[-0.04em]">Good morning, Jordan</h2><p className="mt-1 text-sm text-[#8791a0]">Here’s what’s happening with your revenue.</p></div><button className="self-start rounded-lg bg-[#176b55] px-4 py-2 text-xs font-semibold text-white shadow-sm shadow-[#176b55]/20">+ Add transaction</button></div>

          <div className="mb-5 flex flex-wrap items-center gap-2"><span className="mr-1 text-xs font-semibold text-[#718096]">Date range</span>{(['This month', 'This quarter', 'This year'] as DateRange[]).map(option => <button key={option} onClick={() => setRange(option)} className={`rounded-lg border px-3.5 py-2 text-xs font-semibold transition-colors ${range === option ? 'border-[#176b55] bg-[#176b55] text-white' : 'border-[#dfe4ea] bg-white text-[#536173] hover:border-[#9fc7b9]'}`}>{option}</button>)}</div>

